export const MATERIAL_CLOSURE_RELEASE = Object.freeze({"version":"identity-work-v1","checksum":"156aec912cfbcb3c284f74b0ccb4ec1a4042deb98520b51b9c3741994dcafdcb","manifestSha256":"aaaf3657674128bad81edc0177c36e9c7402c0af4ee19240da2b23782103e7dc","sql":"-- Core schema version identity-work-v1 (closed build artifact).\n\nSET ROLE backbone_gov;\n\n-- gov/identity_person_task_access.sql\n\n-- Installer-only schema lookup permits the table owner to bind policies to these OIDs.\nGRANT USAGE ON SCHEMA gov TO backbone_owner;\n-- Current project access is separate from immutable records of everyone who saw its words.\nCREATE FUNCTION gov.identity_person_task_access(p_task uuid,p_person uuid,p_write boolean) RETURNS boolean\nLANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog\nAS $$\n#variable_conflict use_column\nDECLARE project uuid; permission text; role text;\nBEGIN\n  SELECT project_id INTO project FROM app.identity_task_projects WHERE workspace_id=sec.current_workspace() AND task_id=p_task;\n  IF NOT FOUND THEN RETURN true; END IF;\n  role:=sec.role_of(p_person);\n  IF role IS NULL THEN RETURN false; END IF;\n  SELECT CASE WHEN p.owner_id=p_person THEN 'owner' ELSE a.access END INTO permission\n  FROM app.identity_projects p LEFT JOIN app.identity_project_people a ON a.workspace_id=p.workspace_id AND a.project_id=p.project_id AND a.person_id=p_person\n  WHERE p.workspace_id=sec.current_workspace() AND p.project_id=project;\n  RETURN coalesce(permission='owner' OR (permission='editor' AND role<>'guest') OR (NOT p_write AND permission IS NOT NULL),false);\nEND\n$$;\nREVOKE ALL ON FUNCTION gov.identity_person_task_access(uuid,uuid,boolean) FROM PUBLIC,backbone_operator;\nGRANT EXECUTE ON FUNCTION gov.identity_person_task_access(uuid,uuid,boolean) TO backbone_app,backbone_owner;\n\n-- gov/identity_task_access.sql\n\n-- Restrictive project checks retain legacy crossings and the run-secret accounting exception.\nCREATE FUNCTION gov.identity_task_access(p_task uuid,p_write boolean) RETURNS boolean\nLANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog\nAS $$\n#variable_conflict use_column\nDECLARE project uuid; viewer uuid; principal uuid;\nBEGIN\n  IF p_task IS NULL THEN RETURN true; END IF;\n  SELECT project_id INTO project FROM app.identity_task_projects WHERE workspace_id=sec.current_workspace() AND task_id=p_task;\n  IF NOT FOUND THEN RETURN true; END IF;\n  principal:=sec.current_principal();\n  IF principal=sec.system_principal() THEN RETURN true; END IF;\n  IF principal IS NULL AND NOT sec.names_run() AND coalesce(current_setting('backbone.principal',true),'')='' THEN RETURN true; END IF;\n  viewer:=sec.viewer();\n  RETURN gov.identity_person_task_access(p_task,viewer,p_write);\nEND\n$$;\nREVOKE ALL ON FUNCTION gov.identity_task_access(uuid,boolean) FROM PUBLIC,backbone_operator;\nGRANT EXECUTE ON FUNCTION gov.identity_task_access(uuid,boolean) TO backbone_app,backbone_owner;\n\n-- gov/identity_document_access.sql\n\n-- Restrictive project checks retain legacy crossings and the run-secret accounting exception.\nCREATE FUNCTION gov.identity_document_access(p_document uuid,p_write boolean) RETURNS boolean\nLANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog\nAS $$\n#variable_conflict use_column\nDECLARE task uuid;\nBEGIN\n  SELECT task_id INTO task FROM app.documents WHERE workspace_id=sec.current_workspace() AND id=p_document;\n  IF NOT FOUND THEN RETURN false; END IF;\n  RETURN gov.identity_task_access(task,p_write);\nEND\n$$;\nREVOKE ALL ON FUNCTION gov.identity_document_access(uuid,boolean) FROM PUBLIC,backbone_operator;\nGRANT EXECUTE ON FUNCTION gov.identity_document_access(uuid,boolean) TO backbone_app,backbone_owner;\n\n-- gov/identity_run_access.sql\n\n-- Restrictive project checks retain legacy crossings and the run-secret accounting exception.\nCREATE FUNCTION gov.identity_run_access(p_run uuid,p_write boolean) RETURNS boolean\nLANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog\nAS $$\n#variable_conflict use_column\nDECLARE task uuid;\nBEGIN\n  SELECT task_id INTO task FROM app.runs WHERE workspace_id=sec.current_workspace() AND id=p_run;\n  IF NOT FOUND THEN RETURN false; END IF;\n  RETURN gov.identity_task_access(task,p_write);\nEND\n$$;\nREVOKE ALL ON FUNCTION gov.identity_run_access(uuid,boolean) FROM PUBLIC,backbone_operator;\nGRANT EXECUTE ON FUNCTION gov.identity_run_access(uuid,boolean) TO backbone_app,backbone_owner;\n\n-- gov/identity_run_accounting.sql\n\n-- Restrictive project checks retain legacy crossings and the run-secret accounting exception.\nCREATE FUNCTION gov.identity_run_accounting(p_run uuid) RETURNS boolean\nLANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog\nAS $$\n#variable_conflict use_column\nBEGIN\n  IF NOT sec.names_run() OR p_run IS DISTINCT FROM nullif(current_setting('backbone.run',true),'')::uuid THEN RETURN false; END IF;\n  RETURN EXISTS(SELECT FROM app.runs r JOIN ops.run_secrets s ON s.workspace_id=r.workspace_id AND s.run_id=r.id AND s.fence=r.fence\n    WHERE r.workspace_id=sec.current_workspace() AND r.id=p_run AND s.secret_hash=encode(sha256(convert_to(coalesce(current_setting('backbone.secret',true),''),'UTF8')),'hex'));\nEND\n$$;\nREVOKE ALL ON FUNCTION gov.identity_run_accounting(uuid) FROM PUBLIC,backbone_operator;\nGRANT EXECUTE ON FUNCTION gov.identity_run_accounting(uuid) TO backbone_app,backbone_owner;\n\nSET ROLE backbone_owner;\n\n-- app/identity_task_projects.sql\n\n-- Identity resource state remains tenant-walled and crossing-only.\nCREATE TABLE app.identity_task_projects (workspace_id uuid NOT NULL REFERENCES app.workspaces(id), task_id uuid NOT NULL, project_id uuid NOT NULL, PRIMARY KEY(workspace_id,task_id), FOREIGN KEY(workspace_id,task_id) REFERENCES app.tasks(workspace_id,id), FOREIGN KEY(workspace_id,project_id) REFERENCES app.identity_projects(workspace_id,project_id));\nALTER TABLE app.identity_task_projects ENABLE ROW LEVEL SECURITY;\nALTER TABLE app.identity_task_projects FORCE ROW LEVEL SECURITY;\nCREATE POLICY tenant_wall ON app.identity_task_projects AS RESTRICTIVE FOR ALL TO PUBLIC USING(workspace_id=sec.current_workspace()) WITH CHECK(workspace_id=sec.current_workspace());\nCREATE POLICY crossings ON app.identity_task_projects FOR ALL TO backbone_gov USING(true) WITH CHECK(true);\nREVOKE ALL ON app.identity_task_projects FROM PUBLIC,backbone_app,backbone_operator;\nGRANT SELECT,INSERT,UPDATE,DELETE ON app.identity_task_projects TO backbone_gov;\n\nCREATE POLICY identity_project_read ON app.tasks AS RESTRICTIVE FOR SELECT TO backbone_app USING (gov.identity_task_access(id,false));\nCREATE POLICY identity_project_crossing_read ON app.tasks AS RESTRICTIVE FOR SELECT TO backbone_gov USING (gov.identity_task_access(id,false));\nCREATE POLICY identity_project_insert ON app.tasks AS RESTRICTIVE FOR INSERT TO backbone_gov WITH CHECK (gov.identity_task_access(id,true));\nCREATE POLICY identity_project_update ON app.tasks AS RESTRICTIVE FOR UPDATE TO backbone_gov USING (true) WITH CHECK (gov.identity_task_access(id,true));\nCREATE POLICY identity_project_read ON app.documents AS RESTRICTIVE FOR SELECT TO backbone_app USING (gov.identity_task_access(task_id,false));\nCREATE POLICY identity_project_crossing_read ON app.documents AS RESTRICTIVE FOR SELECT TO backbone_gov USING (gov.identity_task_access(task_id,false));\nCREATE POLICY identity_project_insert ON app.documents AS RESTRICTIVE FOR INSERT TO backbone_gov WITH CHECK (gov.identity_task_access(task_id,true));\nCREATE POLICY identity_project_update ON app.documents AS RESTRICTIVE FOR UPDATE TO backbone_gov USING (true) WITH CHECK (gov.identity_task_access(task_id,true));\nCREATE POLICY identity_project_read ON app.messages AS RESTRICTIVE FOR SELECT TO backbone_app USING (gov.identity_task_access(task_id,false));\nCREATE POLICY identity_project_crossing_read ON app.messages AS RESTRICTIVE FOR SELECT TO backbone_gov USING (gov.identity_task_access(task_id,false));\nCREATE POLICY identity_project_insert ON app.messages AS RESTRICTIVE FOR INSERT TO backbone_gov WITH CHECK (gov.identity_task_access(task_id,true));\nCREATE POLICY identity_project_update ON app.messages AS RESTRICTIVE FOR UPDATE TO backbone_gov USING (true) WITH CHECK (gov.identity_task_access(task_id,true));\nCREATE POLICY identity_project_read ON app.runs AS RESTRICTIVE FOR SELECT TO backbone_app USING (gov.identity_task_access(task_id,false));\nCREATE POLICY identity_project_crossing_read ON app.runs AS RESTRICTIVE FOR SELECT TO backbone_gov USING (CASE WHEN sec.names_run() OR sec.is_admin(sec.current_principal()) THEN true ELSE gov.identity_task_access(task_id,false) END);\nCREATE POLICY identity_project_insert ON app.runs AS RESTRICTIVE FOR INSERT TO backbone_gov WITH CHECK (gov.identity_task_access(task_id,true));\nCREATE POLICY identity_project_update ON app.runs AS RESTRICTIVE FOR UPDATE TO backbone_gov USING (true) WITH CHECK ((gov.identity_task_access(task_id,true) OR gov.identity_run_accounting(id) OR (status IN ('cancelled','failed') AND sec.is_admin(sec.current_principal()))));\nCREATE POLICY identity_project_read ON app.commitments AS RESTRICTIVE FOR SELECT TO backbone_app USING (gov.identity_task_access(task_id,false));\nCREATE POLICY identity_project_crossing_read ON app.commitments AS RESTRICTIVE FOR SELECT TO backbone_gov USING (gov.identity_task_access(task_id,false));\nCREATE POLICY identity_project_insert ON app.commitments AS RESTRICTIVE FOR INSERT TO backbone_gov WITH CHECK (gov.identity_task_access(task_id,true));\nCREATE POLICY identity_project_update ON app.commitments AS RESTRICTIVE FOR UPDATE TO backbone_gov USING (true) WITH CHECK (gov.identity_task_access(task_id,true));\nCREATE POLICY identity_project_read ON app.routines AS RESTRICTIVE FOR SELECT TO backbone_app USING (gov.identity_task_access(task_id,false));\nCREATE POLICY identity_project_crossing_read ON app.routines AS RESTRICTIVE FOR SELECT TO backbone_gov USING (gov.identity_task_access(task_id,false));\nCREATE POLICY identity_project_insert ON app.routines AS RESTRICTIVE FOR INSERT TO backbone_gov WITH CHECK (gov.identity_task_access(task_id,true));\nCREATE POLICY identity_project_update ON app.routines AS RESTRICTIVE FOR UPDATE TO backbone_gov USING (true) WITH CHECK (gov.identity_task_access(task_id,true));\nCREATE POLICY identity_project_read ON app.channel_threads AS RESTRICTIVE FOR SELECT TO backbone_app USING (gov.identity_task_access(task_id,false));\nCREATE POLICY identity_project_crossing_read ON app.channel_threads AS RESTRICTIVE FOR SELECT TO backbone_gov USING (gov.identity_task_access(task_id,false));\nCREATE POLICY identity_project_insert ON app.channel_threads AS RESTRICTIVE FOR INSERT TO backbone_gov WITH CHECK (gov.identity_task_access(task_id,true));\nCREATE POLICY identity_project_update ON app.channel_threads AS RESTRICTIVE FOR UPDATE TO backbone_gov USING (true) WITH CHECK (gov.identity_task_access(task_id,true));\nCREATE POLICY identity_project_read ON app.task_people AS RESTRICTIVE FOR SELECT TO backbone_app USING (gov.identity_task_access(task_id,false));\nCREATE POLICY identity_project_crossing_read ON app.task_people AS RESTRICTIVE FOR SELECT TO backbone_gov USING (gov.identity_task_access(task_id,false));\nCREATE POLICY identity_project_insert ON app.task_people AS RESTRICTIVE FOR INSERT TO backbone_gov WITH CHECK (gov.identity_task_access(task_id,true));\nCREATE POLICY identity_project_update ON app.task_people AS RESTRICTIVE FOR UPDATE TO backbone_gov USING (true) WITH CHECK (gov.identity_task_access(task_id,true));\nCREATE POLICY identity_project_read ON app.episodes AS RESTRICTIVE FOR SELECT TO backbone_app USING (gov.identity_task_access(task_id,false));\nCREATE POLICY identity_project_crossing_read ON app.episodes AS RESTRICTIVE FOR SELECT TO backbone_gov USING (gov.identity_task_access(task_id,false));\nCREATE POLICY identity_project_insert ON app.episodes AS RESTRICTIVE FOR INSERT TO backbone_gov WITH CHECK (gov.identity_task_access(task_id,true));\nCREATE POLICY identity_project_update ON app.episodes AS RESTRICTIVE FOR UPDATE TO backbone_gov USING (true) WITH CHECK (gov.identity_task_access(task_id,true));\nCREATE POLICY identity_project_read ON app.effects AS RESTRICTIVE FOR SELECT TO backbone_app USING (gov.identity_task_access(task_id,false));\nCREATE POLICY identity_project_crossing_read ON app.effects AS RESTRICTIVE FOR SELECT TO backbone_gov USING (sec.is_admin(sec.current_principal()) OR gov.identity_task_access(task_id,false));\nCREATE POLICY identity_project_insert ON app.effects AS RESTRICTIVE FOR INSERT TO backbone_gov WITH CHECK (gov.identity_task_access(task_id,true));\nCREATE POLICY identity_project_update ON app.effects AS RESTRICTIVE FOR UPDATE TO backbone_gov USING (true) WITH CHECK ((gov.identity_task_access(task_id,true) OR (status='cancelled' AND sec.is_admin(sec.current_principal()))));\nCREATE POLICY identity_project_read ON app.document_versions AS RESTRICTIVE FOR SELECT TO backbone_app USING (gov.identity_document_access(document_id,false));\nCREATE POLICY identity_project_crossing_read ON app.document_versions AS RESTRICTIVE FOR SELECT TO backbone_gov USING (gov.identity_document_access(document_id,false));\nCREATE POLICY identity_project_insert ON app.document_versions AS RESTRICTIVE FOR INSERT TO backbone_gov WITH CHECK (gov.identity_document_access(document_id,true));\nCREATE POLICY identity_project_update ON app.document_versions AS RESTRICTIVE FOR UPDATE TO backbone_gov USING (true) WITH CHECK (gov.identity_document_access(document_id,true));\nCREATE POLICY identity_project_read ON app.run_steps AS RESTRICTIVE FOR SELECT TO backbone_app USING (gov.identity_run_access(run_id,false));\nCREATE POLICY identity_project_crossing_read ON app.run_steps AS RESTRICTIVE FOR SELECT TO backbone_gov USING (gov.identity_run_access(run_id,false));\nCREATE POLICY identity_project_insert ON app.run_steps AS RESTRICTIVE FOR INSERT TO backbone_gov WITH CHECK (gov.identity_run_access(run_id,true));\nCREATE POLICY identity_project_update ON app.run_steps AS RESTRICTIVE FOR UPDATE TO backbone_gov USING (true) WITH CHECK (gov.identity_run_access(run_id,true));\n\n-- app/identity_directory.sql\n\n-- Identity resource state remains tenant-walled and crossing-only.\nCREATE TABLE app.identity_directory (workspace_id uuid NOT NULL REFERENCES app.workspaces(id), principal_id uuid NOT NULL, issuer text NOT NULL, subject text NOT NULL, user_name text NOT NULL, display_name text, revision bigint NOT NULL DEFAULT 1, PRIMARY KEY(workspace_id,principal_id), UNIQUE(workspace_id,issuer,user_name), FOREIGN KEY(workspace_id,principal_id) REFERENCES app.principals(workspace_id,id), FOREIGN KEY(workspace_id,issuer,subject) REFERENCES app.identity_accounts(workspace_id,issuer,subject));\nALTER TABLE app.identity_directory ENABLE ROW LEVEL SECURITY;\nALTER TABLE app.identity_directory FORCE ROW LEVEL SECURITY;\nCREATE POLICY tenant_wall ON app.identity_directory AS RESTRICTIVE FOR ALL TO PUBLIC USING(workspace_id=sec.current_workspace()) WITH CHECK(workspace_id=sec.current_workspace());\nCREATE POLICY crossings ON app.identity_directory FOR ALL TO backbone_gov USING(true) WITH CHECK(true);\nREVOKE ALL ON app.identity_directory FROM PUBLIC,backbone_app,backbone_operator;\nGRANT SELECT,INSERT,UPDATE,DELETE ON app.identity_directory TO backbone_gov;\n\nSET ROLE backbone_gov;\n\n-- gov/task_visible_to.sql\n\n-- The table-owner policy bindings are complete; retain the original namespace grants.\nREVOKE USAGE ON SCHEMA gov FROM backbone_owner;\n-- Keep legacy audiences, while checking current project access for the named reader.\nCREATE OR REPLACE FUNCTION sec.task_visible_to(p_task uuid,p_person uuid) RETURNS boolean\nLANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog\nAS $$\n  SELECT gov.identity_person_task_access(p_task,p_person,false) AND EXISTS (\n    SELECT FROM app.tasks t\n    WHERE t.workspace_id=sec.current_workspace() AND t.id=p_task\n      AND (t.visibility='workspace' OR p_person IN(t.requested_by,t.on_behalf_of)\n        OR EXISTS(SELECT FROM app.task_people tp WHERE tp.workspace_id=t.workspace_id AND tp.task_id=t.id AND tp.person_id=p_person)))\n$$;\n\n-- gov/identity_project_share.sql\n\n-- Identity operations serialize admission and revocation before observing authority.\nCREATE OR REPLACE FUNCTION gov.identity_project_share(p_project uuid, p_person uuid, p_access text) RETURNS uuid\nLANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog\nAS $$\n#variable_conflict use_column\nDECLARE ws uuid:=sec.current_workspace(); me uuid;\nBEGIN\n  PERFORM pg_advisory_xact_lock(hashtextextended('identity:'||ws::text,17));\n  PERFORM gov._lock_workspace(); me:=gov._person();\n  IF NOT EXISTS(SELECT FROM app.identity_projects WHERE workspace_id=ws AND project_id=p_project AND owner_id=me) THEN RAISE EXCEPTION 'denied: only the project owner shares it'; END IF;\n  IF p_access IS NOT NULL AND p_access NOT IN ('viewer','editor') THEN RAISE EXCEPTION 'invalid: project access'; END IF;\n  IF sec.role_of(p_person) IS NULL THEN RAISE EXCEPTION 'not_found: no active person'; END IF;\n  IF p_person=me THEN RAISE EXCEPTION 'invalid: the project owner keeps ownership'; END IF;\n  IF sec.role_of(p_person)='guest' AND p_access='editor' THEN RAISE EXCEPTION 'role: guests only view'; END IF;\n  IF p_access IS NULL THEN DELETE FROM app.identity_project_people WHERE workspace_id=ws AND project_id=p_project AND person_id=p_person;\n  ELSE INSERT INTO app.identity_project_people(workspace_id,project_id,person_id,access) VALUES(ws,p_project,p_person,p_access)\n    ON CONFLICT(workspace_id,project_id,person_id) DO UPDATE SET access=EXCLUDED.access;\n  END IF;\n  -- Audience history is retained. Revoking a project grant does not make words\n  -- already shared private again; restrictive policies enforce current access.\n  IF p_access IS NOT NULL THEN\n    INSERT INTO app.task_people(workspace_id,task_id,person_id)\n    SELECT ws,t.task_id,p_person FROM app.identity_task_projects t WHERE t.workspace_id=ws AND t.project_id=p_project\n    ON CONFLICT(workspace_id,task_id,person_id) DO NOTHING;\n  END IF;\n  PERFORM gov._append('identity.project_shared',p_project::text,jsonb_build_object('person',p_person,'access',p_access));\n  RETURN p_project;\nEND\n$$;\nREVOKE ALL ON FUNCTION gov.identity_project_share(uuid,uuid,text) FROM PUBLIC, backbone_operator;\nGRANT EXECUTE ON FUNCTION gov.identity_project_share(uuid,uuid,text) TO backbone_app;\n\n-- gov/identity_register_project.sql\n\n-- Explicit project/directory/automation authority; never inferred from a renderer's identity.\nCREATE FUNCTION gov.identity_register_project(p_project uuid) RETURNS uuid\nLANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog\nAS $$\n#variable_conflict use_column\nBEGIN\n  PERFORM gov._person();\n  IF EXISTS(SELECT FROM app.identity_projects WHERE workspace_id=sec.current_workspace() AND project_id=p_project) THEN RETURN p_project; END IF;\n  RETURN gov.identity_project_create(p_project);\nEND\n$$;\nREVOKE ALL ON FUNCTION gov.identity_register_project(uuid) FROM PUBLIC,backbone_operator;\nGRANT EXECUTE ON FUNCTION gov.identity_register_project(uuid) TO backbone_app;\n\n-- gov/identity_bind_task.sql\n\n-- Bind an existing private task only by its own requester in an owned project.\nCREATE FUNCTION gov.identity_bind_task(p_project uuid,p_task uuid) RETURNS uuid\nLANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog\nAS $$\n#variable_conflict use_column\nDECLARE me uuid;\nBEGIN\n  PERFORM gov._lock_workspace(); me:=gov._person();\n  IF coalesce(gov.identity_project_access(p_project),'')<>'owner' OR NOT EXISTS(SELECT FROM app.tasks WHERE workspace_id=sec.current_workspace() AND id=p_task AND requested_by=me) THEN RAISE EXCEPTION 'denied: task binding belongs to its requester'; END IF;\n  INSERT INTO app.identity_task_projects(workspace_id,task_id,project_id) VALUES(sec.current_workspace(),p_task,p_project) ON CONFLICT(workspace_id,task_id) DO NOTHING;\n  RETURN p_task;\nEND\n$$;\nREVOKE ALL ON FUNCTION gov.identity_bind_task(uuid,uuid) FROM PUBLIC,backbone_operator;\nGRANT EXECUTE ON FUNCTION gov.identity_bind_task(uuid,uuid) TO backbone_app;\n\n-- gov/identity_project_sharing.sql\n\n-- Only the project owner inspects its grants. Seeing the project is not authority to share it.\nCREATE FUNCTION gov.identity_project_sharing(p_project uuid) RETURNS TABLE(person uuid,access text)\nLANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog\nAS $$\nBEGIN\n  IF coalesce(gov.identity_project_access(p_project),'')<>'owner' THEN RAISE EXCEPTION 'denied: project ownership required'; END IF;\n  RETURN QUERY SELECT a.person_id,a.access FROM app.identity_project_people a WHERE a.workspace_id=sec.current_workspace() AND a.project_id=p_project ORDER BY a.person_id;\nEND\n$$;\nREVOKE ALL ON FUNCTION gov.identity_project_sharing(uuid) FROM PUBLIC,backbone_operator;\nGRANT EXECUTE ON FUNCTION gov.identity_project_sharing(uuid) TO backbone_app;\n\n-- gov/identity_create_task.sql\n\n-- Explicit project/directory/automation authority; never inferred from a renderer's identity.\nCREATE FUNCTION gov.identity_create_task(p_project uuid, p_title text) RETURNS uuid\nLANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog\nAS $$\n#variable_conflict use_column\nDECLARE me uuid; task uuid;\nBEGIN\n  PERFORM gov._lock_workspace(); me:=gov._person();\n  IF gov.identity_project_access(p_project) NOT IN ('owner','editor') OR gov.identity_project_access(p_project) IS NULL THEN RAISE EXCEPTION 'denied: project is read only or unavailable'; END IF;\n  task:=gov.create_task(me,me,p_title,NULL,NULL);\n  INSERT INTO app.identity_task_projects(workspace_id,task_id,project_id) VALUES(sec.current_workspace(),task,p_project);\n  INSERT INTO app.task_people(workspace_id,task_id,person_id)\n  SELECT sec.current_workspace(),task,p.owner_id FROM app.identity_projects p WHERE p.workspace_id=sec.current_workspace() AND p.project_id=p_project AND p.owner_id<>me\n  UNION SELECT sec.current_workspace(),task,a.person_id FROM app.identity_project_people a WHERE a.workspace_id=sec.current_workspace() AND a.project_id=p_project AND a.person_id<>me\n  ON CONFLICT(workspace_id,task_id,person_id) DO NOTHING;\n  RETURN task;\nEND\n$$;\nREVOKE ALL ON FUNCTION gov.identity_create_task(uuid,text) FROM PUBLIC,backbone_operator;\nGRANT EXECUTE ON FUNCTION gov.identity_create_task(uuid,text) TO backbone_app;\n\n-- gov/identity_document_version.sql\n\n-- Explicit project/directory/automation authority; never inferred from a renderer's identity.\nCREATE FUNCTION gov.identity_document_version(p_project uuid, p_document uuid) RETURNS integer\nLANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog\nAS $$\n#variable_conflict use_column\nDECLARE version integer;\nBEGIN\n  IF gov.identity_project_access(p_project) IS NULL THEN RAISE EXCEPTION 'denied: project unavailable'; END IF;\n  SELECT d.version INTO version FROM app.documents d JOIN app.identity_task_projects t ON t.workspace_id=d.workspace_id AND t.task_id=d.task_id\n  WHERE d.workspace_id=sec.current_workspace() AND d.id=p_document AND t.project_id=p_project;\n  RETURN version;\nEND\n$$;\nREVOKE ALL ON FUNCTION gov.identity_document_version(uuid,uuid) FROM PUBLIC,backbone_operator;\nGRANT EXECUTE ON FUNCTION gov.identity_document_version(uuid,uuid) TO backbone_app;\n\n-- gov/identity_revise_document.sql\n\n-- Explicit project/directory/automation authority; never inferred from a renderer's identity.\nCREATE FUNCTION gov.identity_revise_document(p_project uuid, p_document uuid, p_content text, p_base integer) RETURNS integer\nLANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog\nAS $$\n#variable_conflict use_column\nDECLARE me uuid; version integer; ws uuid:=sec.current_workspace();\nBEGIN\n  PERFORM gov._lock_workspace(); me:=gov._person();\n  IF coalesce(gov.identity_project_access(p_project),'') NOT IN ('owner','editor') THEN RAISE EXCEPTION 'denied: project is read only'; END IF;\n  SELECT d.version INTO version FROM app.documents d JOIN app.identity_task_projects t ON t.workspace_id=d.workspace_id AND t.task_id=d.task_id\n  WHERE d.workspace_id=ws AND d.id=p_document AND t.project_id=p_project FOR UPDATE OF d;\n  IF NOT FOUND THEN RAISE EXCEPTION 'not_found: no document in this project'; END IF;\n  IF version<>p_base THEN RAISE EXCEPTION 'stale: document changed'; END IF;\n  UPDATE app.documents SET content=p_content,updated_by=me,content_author=me,via_effect=NULL WHERE workspace_id=ws AND id=p_document;\n  SELECT d.version INTO version FROM app.documents d WHERE d.workspace_id=ws AND d.id=p_document;\n  PERFORM gov._append('document.revised',p_document::text,jsonb_build_object('version',version));\n  RETURN version;\nEND\n$$;\nREVOKE ALL ON FUNCTION gov.identity_revise_document(uuid,uuid,text,integer) FROM PUBLIC,backbone_operator;\nGRANT EXECUTE ON FUNCTION gov.identity_revise_document(uuid,uuid,text,integer) TO backbone_app;\n\n-- gov/identity_directory_create.sql\n\n-- Explicit project/directory/automation authority; never inferred from a renderer's identity.\nCREATE FUNCTION gov.identity_directory_create(p_issuer text, p_subject text, p_username text, p_name text) RETURNS uuid\nLANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog\nAS $$\n#variable_conflict use_column\nDECLARE me uuid; person uuid:=gen_random_uuid(); ws uuid:=sec.current_workspace();\nBEGIN\n  PERFORM pg_advisory_xact_lock(hashtextextended('identity:'||ws::text,17)); PERFORM gov._lock_workspace(); me:=gov._admin();\n  IF nullif(p_issuer,'') IS NULL OR nullif(p_subject,'') IS NULL OR nullif(p_username,'') IS NULL THEN RAISE EXCEPTION 'invalid: directory account'; END IF;\n  INSERT INTO app.principals(workspace_id,id,kind,role,name,user_id) VALUES(ws,person,'person','member',coalesce(nullif(p_name,''),p_username),person::text);\n  INSERT INTO app.identity_accounts(workspace_id,principal_id,issuer,subject) VALUES(ws,person,p_issuer,p_subject);\n  INSERT INTO app.identity_directory(workspace_id,principal_id,issuer,subject,user_name,display_name) VALUES(ws,person,p_issuer,p_subject,p_username,p_name);\n  PERFORM gov._append('identity.provisioned',person::text,jsonb_build_object('by',me));\n  RETURN person;\nEND\n$$;\nREVOKE ALL ON FUNCTION gov.identity_directory_create(text,text,text,text) FROM PUBLIC,backbone_operator;\nGRANT EXECUTE ON FUNCTION gov.identity_directory_create(text,text,text,text) TO backbone_app;\n\n-- gov/identity_directory_list.sql\n\n-- Explicit project/directory/automation authority; never inferred from a renderer's identity.\nCREATE FUNCTION gov.identity_directory_list(p_issuer text) RETURNS TABLE(id uuid, username text, external_id text, display_name text, active boolean, revision bigint)\nLANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog\nAS $$\n#variable_conflict use_column\nBEGIN\n  PERFORM gov._admin();\n  RETURN QUERY SELECT p.id,d.user_name,d.subject,d.display_name,p.status='active',d.revision\n  FROM app.identity_directory d JOIN app.principals p ON p.workspace_id=d.workspace_id AND p.id=d.principal_id\n  WHERE d.workspace_id=sec.current_workspace() AND d.issuer=p_issuer ORDER BY p.id;\nEND\n$$;\nREVOKE ALL ON FUNCTION gov.identity_directory_list(text) FROM PUBLIC,backbone_operator;\nGRANT EXECUTE ON FUNCTION gov.identity_directory_list(text) TO backbone_app;\n\n-- gov/identity_directory_update.sql\n\n-- Explicit project/directory/automation authority; never inferred from a renderer's identity.\nCREATE FUNCTION gov.identity_directory_update(p_issuer text, p_person uuid, p_name text, p_active boolean, p_revision bigint) RETURNS uuid\nLANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog\nAS $$\n#variable_conflict use_column\nDECLARE me uuid; d record; status text; ws uuid:=sec.current_workspace();\nBEGIN\n  PERFORM pg_advisory_xact_lock(hashtextextended('identity:'||ws::text,17)); PERFORM gov._lock_workspace(); me:=gov._admin();\n  SELECT * INTO d FROM app.identity_directory WHERE workspace_id=ws AND principal_id=p_person AND issuer=p_issuer FOR UPDATE;\n  IF NOT FOUND THEN RAISE EXCEPTION 'not_found: no directory person'; END IF;\n  IF d.revision<>p_revision THEN RAISE EXCEPTION 'stale: directory changed'; END IF;\n  SELECT p.status INTO status FROM app.principals p WHERE p.workspace_id=ws AND p.id=p_person;\n  IF status='removed' AND p_active THEN RAISE EXCEPTION 'revoked: removed access stays removed'; END IF;\n  IF NOT p_active THEN PERFORM gov.identity_remove(p_person); END IF;\n  UPDATE app.identity_directory SET display_name=p_name,revision=revision+1 WHERE workspace_id=ws AND principal_id=p_person;\n  IF status='active' THEN UPDATE app.principals SET name=coalesce(nullif(p_name,''),d.user_name) WHERE workspace_id=ws AND id=p_person; END IF;\n  PERFORM gov._append('identity.directory_changed',p_person::text,jsonb_build_object('active',p_active));\n  RETURN p_person;\nEND\n$$;\nREVOKE ALL ON FUNCTION gov.identity_directory_update(text,uuid,text,boolean,bigint) FROM PUBLIC,backbone_operator;\nGRANT EXECUTE ON FUNCTION gov.identity_directory_update(text,uuid,text,boolean,bigint) TO backbone_app;\n\n-- gov/identity_automation_create.sql\n\n-- Explicit project/directory/automation authority; never inferred from a renderer's identity.\nCREATE FUNCTION gov.identity_automation_create(p_person uuid, p_project uuid, p_name text, p_piece uuid) RETURNS uuid\nLANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog\nAS $$\n#variable_conflict use_column\nDECLARE me uuid; agent uuid; mandate uuid; ws uuid:=sec.current_workspace();\nBEGIN\n  PERFORM pg_advisory_xact_lock(hashtextextended('identity:'||ws::text,17)); PERFORM gov._lock_workspace(); me:=gov._admin();\n  IF coalesce(gov.identity_project_access(p_project),'') NOT IN ('owner','editor') THEN RAISE EXCEPTION 'denied: project unavailable'; END IF;\n  IF sec.role_of(p_person) IS NULL OR sec.role_of(p_person)='guest' OR nullif(btrim(p_name),'') IS NULL THEN RAISE EXCEPTION 'role: automation needs a named active person who may work'; END IF;\n  PERFORM set_config('backbone.principal',p_person::text,true);\n  IF coalesce(gov.identity_project_access(p_project),'') NOT IN ('owner','editor') THEN RAISE EXCEPTION 'denied: the named person cannot work in this project'; END IF;\n  agent:=gov.create_agent(p_name,'worker');\n  mandate:=gov.issue_mandate(agent,NULL,jsonb_build_array(p_project::text),'\"*\"','\"*\"','\"*\"',3::smallint,NULL,NULL,NULL,NULL,clock_timestamp()+interval '1 year',CASE WHEN p_piece IS NULL THEN 'direct' ELSE 'piece' END,jsonb_build_object('identityAutomation',true,'project',p_project,'createdBy',me),p_piece);\n  PERFORM set_config('backbone.principal',me::text,true);\n  PERFORM gov._append('identity.automation_created',agent::text,jsonb_build_object('person',p_person,'project',p_project,'mandate',mandate),me);\n  RETURN agent;\nEND\n$$;\nREVOKE ALL ON FUNCTION gov.identity_automation_create(uuid,uuid,text,uuid) FROM PUBLIC,backbone_operator;\nGRANT EXECUTE ON FUNCTION gov.identity_automation_create(uuid,uuid,text,uuid) TO backbone_app;\n\n-- gov/identity_automations.sql\n\n-- Explicit project/directory/automation authority; never inferred from a renderer's identity.\nCREATE FUNCTION gov.identity_automations() RETURNS TABLE(id uuid, name text, person uuid, project uuid, mandate uuid, piece uuid, revoked boolean)\nLANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog\nAS $$\n#variable_conflict use_column\nBEGIN\n  PERFORM gov._admin();\n  RETURN QUERY SELECT a.id,a.name,a.owner_id,(m.intent->>'project')::uuid,m.id,m.piece_id,m.revoked_at IS NOT NULL OR m.expires_at<=clock_timestamp() OR p.status<>'active'\n  FROM app.principals a JOIN app.mandates m ON m.workspace_id=a.workspace_id AND m.subject_id=a.id JOIN app.principals p ON p.workspace_id=a.workspace_id AND p.id=a.owner_id\n  WHERE a.workspace_id=sec.current_workspace() AND a.kind='agent' AND m.intent->>'identityAutomation'='true' ORDER BY a.created_at,a.id;\nEND\n$$;\nREVOKE ALL ON FUNCTION gov.identity_automations() FROM PUBLIC,backbone_operator;\nGRANT EXECUTE ON FUNCTION gov.identity_automations() TO backbone_app;\n\n-- gov/identity_automation_revoke.sql\n\n-- Explicit project/directory/automation authority; never inferred from a renderer's identity.\nCREATE FUNCTION gov.identity_automation_revoke(p_agent uuid) RETURNS uuid\nLANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog\nAS $$\n#variable_conflict use_column\nDECLARE me uuid; m record;\nBEGIN\n  PERFORM pg_advisory_xact_lock(hashtextextended('identity:'||sec.current_workspace()::text,17)); PERFORM gov._lock_workspace(); me:=gov._admin();\n  IF NOT EXISTS(SELECT FROM app.mandates WHERE workspace_id=sec.current_workspace() AND subject_id=p_agent AND intent->>'identityAutomation'='true') THEN RAISE EXCEPTION 'not_found: no automation'; END IF;\n  FOR m IN SELECT id FROM app.mandates WHERE workspace_id=sec.current_workspace() AND subject_id=p_agent AND revoked_at IS NULL LOOP PERFORM gov.revoke_mandate(m.id); END LOOP;\n  PERFORM gov._append('identity.automation_revoked',p_agent::text,'{}',me);\n  RETURN p_agent;\nEND\n$$;\nREVOKE ALL ON FUNCTION gov.identity_automation_revoke(uuid) FROM PUBLIC,backbone_operator;\nGRANT EXECUTE ON FUNCTION gov.identity_automation_revoke(uuid) TO backbone_app;\n\nRESET ROLE;\n"} as const);
